public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Initialize a visited array to keep track of visited n-tersections
    boolean[] visited = new boolean[n];
    // Initialize a queue to perform breadth-first search
    Queue<int[]> queue = new LinkedList<>();

    // Add the starting n-tersection to the queue and mark it as visited
    queue.add(start);
    visited[start[0] * n + start[1]] = true;

    // Perform breadth-first search until the queue is empty
    while (!queue.isEmpty()) {
        int[] current = queue.poll();
        // If the current n-tersection is the ending n-tersection, return "can be travelled"
        if (Arrays.equals(current, end)) {
            return "can be travelled";
        }
        // Loop through all the paths starting from the current n-tersection
        for (int[] path : paths) {
            // Get the next n-tersection coordinates
            int nextX = current[0] + path[0];
            int nextY = current[1] + path[1];

            // If the next n-tersection is outside the n-teresting space, continue
            if (nextX < 0 || nextX >= n || nextY < 0 || nextY >= n) {
                continue;
            }

            // If the next n-tersection is already visited, continue
            if (visited[nextX * n + nextY]) {
                continue;
            }

            // Add the next n-tersection to the queue and mark it as visited
            queue.add(new int[] {nextX, nextY});
            visited[nextX * n + nextY] = true;
        }
    }

    // If the ending n-tersection was not visited, return "cannot be travelled"
    return "cannot be travelled";
}

