public int minOperations(int n) {
    int[] arr = new int[n];
    for (int i = 0; i < n; i++) {
        arr[i] = (2 * i) + 1;
    }
    int minOperations = 0;
    while (!allEqual(arr)) {
        int x = 0;
        int y = n - 1;
        int diff = arr[x] - arr[y];
        if (diff > 0) {
            arr[y] += diff;
            arr[x] -= diff;
            minOperations++;
        } else if (diff < 0) {
            arr[x] -= diff;
            arr[y] += diff;
            minOperations++;
        }
    }
    return minOperations;
}

