        digits.add(Character.getNumericValue(c));
    }

    // Sort the list of digits in descending order
    Collections.sort(digits, Collections.reverseOrder());

    // Create a string builder to construct the rearranged number
    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < digits.size(); i++) {
        sb.append(String.valueOf(digits.get(i)));
    }

    // Convert the string builder to an integer
    int rearrangedNumber = Integer.parseInt(sb.toString());

    // If the rearranged number is greater than the input number, return it
    if (rearrangedNumber > n) {
        return rearrangedNumber;
    }

    // If the rearranged number is not greater than the input number, return -1
    return -1;
}

public static List<String> centerSymmetricNumbers(int n) {
    List<String> symmetricNumbers = new ArrayList<>();
    for (int i = 1; i <= 9; i++) {
        String number = String.format("%0" + n + "d", i);
        if (isCenterSymmetric(number)) {
            symmetricNumbers.add(number);
        }
    }
    return symmetricNumbers;
}

private static boolean isCenterSymmetric(String number) {
    int length = number.length();
    for (int i = 0; i < length / 2; i++) {
        if (number.charAt(i) != number.charAt(length - 1 - i)) {
            return false;
        }
    }
    return true;
}

public static boolean isBoomerang(int[][] points) {
    // Step 1: Check if the input array is valid
    if (points == null || points.length != 3) {
        return false;
    }

    // Step 2: Check if the three points are distinct
    if (points[0][0] == points[1][0] && points[0][1] == points[1][1]) {
        return false;
    }

    // Step 3: Check if the slope of the line between the first two points is equal to the slope of the line between the second and third points
    double m1 = (double) (points[1][1] - points[0][1]) / (points[1][0] - points[0][0]);
    double m2 = (double) (points[2][1] - points[1][1]) / (points[2][0] - points[1][0]);
    if (m1 == m2) {
        return false;
    }

    // Step 4: Check if the three points are not collinear
    if (((points[1][0] - points[0][0]) * (points[2][1] - points[0][1])) - ((points[2][0] - points[0][0]) * (points[1][1] - points[0][1])) == 0) {
        return false;
    }

    // Step 5: Check if the three points form a boomerang
    if (((points[1][0] - points[0][0]) * (points[2][1] - points[1][1])) - ((points[2][0] - points[1][0]) * (points[1][1] - points[0][1])) != 0) {
        return true;
    }

    return false;
}

public static int findNthUglyNumber(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be a positive integer.");
        }

        int count = 0;
        int i = 0;
        while (count < n) {
            i++;
            if (isUglyNumber(i)) {
                count++;
            }
        }

        return i;
    }

private static boolean isUglyNumber(int i) {
        return i % 2 == 0 || i % 3 == 0 || i % 5 == 0;
    }

public static int calculateEnergy(String s) {
    char prevChar = '\0';
    int maxLength = 0;
    int currentLength = 0;
    for (char c : s.toCharArray()) {
        if (c == prevChar) {
            currentLength++;
        } else {
            maxLength = Math.max(maxLength, currentLength);
            currentLength = 1;
            prevChar = c;
        }
    }
    return maxLength;
}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    for (int i = 1; i <= n; i++) {
        String str = String.valueOf(i);
        int len = str.length();
        int j = 0;
        while (j < len && str.charAt(j) == result.get(j)) {
            j++;
        }
        if (j == len) {
            result.add(i);
        }
    }
    return result;
}

public static int calculateUniqueSum(int[] nums) {
    // Handle null input
    if (nums == null) {
        throw new IllegalArgumentException("Input array is null");
    }

    // Initialize a set to store unique elements
    Set<Integer> uniqueElements = new HashSet<>();

    // Loop through the input array and add unique elements to the set
    for (int num : nums) {
        if (!uniqueElements.contains(num)) {
            uniqueElements.add(num);
        }
    }

    // Calculate the sum of unique elements
    int sum = 0;
    for (int element : uniqueElements) {
        sum += element;
    }

    return sum;
}

public static int minPerfectSquareSum(int n) {
    int[] squares = new int[n+1];
    squares[0] = 0;
    int sum = 0;

    for (int i = 1; i <= n; i++) {
        sum += i*i;
        if (sum > n) {
            return i - 1;
        }
        squares[i] = sum;
    }

    return squares.length;
}

public static String reverseWords(String s) {
    return Arrays.stream(s.split(" "))
            .map(word -> new StringBuilder(word).reverse().toString())
            .collect(Collectors.joining(" "));
}
